CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', vehicle text NOT NULL DEFAULT 'light', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own profile" ON public.profiles FOR ALL TO authenticated USING (auth.uid() = id) WITH CHECK (auth.uid() = id);
CREATE FUNCTION public.create_learner_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'display_name', '')); RETURN NEW; END; $$;
CREATE TRIGGER create_learner_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_learner_profile();
CREATE TABLE public.question_attempts (id uuid PRIMARY KEY, user_id uuid NOT NULL, question_id text NOT NULL, category integer NOT NULL, correct boolean NOT NULL, created_at timestamptz NOT NULL);
GRANT SELECT, INSERT ON public.question_attempts TO authenticated;
GRANT ALL ON public.question_attempts TO service_role;
ALTER TABLE public.question_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own attempts read" ON public.question_attempts FOR SELECT TO authenticated USING(auth.uid() = user_id);
CREATE POLICY "Own attempts insert" ON public.question_attempts FOR INSERT TO authenticated WITH CHECK(auth.uid() = user_id);
CREATE INDEX question_attempts_user_date ON public.question_attempts(user_id, created_at DESC);
CREATE TABLE public.test_attempts (id uuid PRIMARY KEY, user_id uuid NOT NULL, mode text NOT NULL, results jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL);
GRANT SELECT, INSERT ON public.test_attempts TO authenticated;
GRANT ALL ON public.test_attempts TO service_role;
ALTER TABLE public.test_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own tests read" ON public.test_attempts FOR SELECT TO authenticated USING(auth.uid() = user_id);
CREATE POLICY "Own tests insert" ON public.test_attempts FOR INSERT TO authenticated WITH CHECK(auth.uid() = user_id);
CREATE INDEX test_attempts_user_date ON public.test_attempts(user_id, created_at DESC);